using AcxiomCRM.Data;using AcxiomCRM.Models;using AcxiomCRM.Services;using AcxiomCRM.ViewModels;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Controllers.Api;
[ApiController,Route("api/opportunities")] public class OpportunitiesApiController(CrmDb db,CrmService crm,AuditService audit):ControllerBase {
[HttpGet] public async Task<IActionResult> List(int page=1){page=Math.Clamp(page,1,100000);return Ok((await crm.Scope<Opportunity>().OrderBy(x=>x.Id).Skip((page-1)*50).Take(50).ToListAsync()).Select(x=>new{x.Id,Data=OpportunityInput.From(x)}));}
[HttpGet("{id:int}")] public async Task<IActionResult> Get(int id){var e=await crm.Scope<Opportunity>().FirstOrDefaultAsync(x=>x.Id==id);return e==null?NotFound():Ok(new{e.Id,Data=OpportunityInput.From(e)});}
[HttpPost] public Task<IActionResult> Create(OpportunityInput input)=>Save(null,input);
[HttpPut("{id:int}")] public Task<IActionResult> Update(int id,OpportunityInput input)=>Save(id,input);
async Task<IActionResult> Save(int? id,OpportunityInput input){var e=id==null?new Opportunity():await crm.Scope<Opportunity>().FirstOrDefaultAsync(x=>x.Id==id);if(e==null)return NotFound();var before=id==null?null:OpportunityInput.From(e);string? oldStatus=null;input.Apply(e);e.AssignedTo=input.AssignedTo??(id==null?crm.Id:e.AssignedTo);var error=await crm.Validate(e,id==null?null:oldStatus);if(error!=null)return BadRequest(new{error});await using var tx=await db.Database.BeginTransactionAsync();try{if(id==null)db.Add(e);await db.SaveChangesAsync();audit.Add(id==null?"Create":"Update","Opportunity",e.Id.ToString(),before,OpportunityInput.From(e));await db.SaveChangesAsync();await tx.CommitAsync();return id==null?CreatedAtAction(nameof(Get),new{id=e.Id},new{e.Id,Data=OpportunityInput.From(e)}):Ok(new{e.Id,Data=OpportunityInput.From(e)});}catch(DbUpdateException){await tx.RollbackAsync();return Conflict(new{error="Duplicate or invalid record."});}}
[HttpDelete("{id:int}")] public async Task<IActionResult> Delete(int id){var e=await crm.Scope<Opportunity>().FirstOrDefaultAsync(x=>x.Id==id);if(e==null)return NotFound();e.IsDeleted=true;audit.Add("Delete","Opportunity",id.ToString(),OpportunityInput.From(e));await db.SaveChangesAsync();return NoContent();}
}
